(() => {
 const D=window.OPERATOR_PROFILES||{records:{}};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const selected=new Map();
 const get=id=>D.records[typeof id==='string'?id:id.id];
 const facts=rows=>`<dl class="dossier-facts">${rows.map(x=>`<div class="${['undisclosed','not-listed'].includes(x.state)?'is-unpublished':''}"><dt>${esc(x.label)}</dt><dd>${esc(x.value)}</dd></div>`).join('')}</dl>`;
 function render(p,full){const record=get(p.id);if(!record)return '';if(!full)return '<section class="dossier-preview"><h2>干员档案</h2><p>开启完整阅读后，可查看种族、年龄、源石技艺及本形态的体检资料。</p></section>';
 const i=selected.get(p.id)||0,o=record.options[i]||record.options[0],rating=o.test['源石技艺适应性'];
 const tests=Object.entries(o.test).filter(([k])=>k!=='源石技艺适应性').map(([label,value])=>({label,value}));
 return `<section class="operator-dossier" id="operator-dossier" data-profile-id="${p.id}"><div class="dossier-heading"><div><div class="eyebrow">OPERATOR DOSSIER</div><h2>干员档案</h2></div><span>${esc(record.number||'公开档案')}</span></div>${record.options.length>1?`<label class="dossier-version">档案版本<select data-profile-variant aria-label="选择干员档案版本">${record.options.map((x,n)=>`<option value="${n}" ${n===i?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label>`:`<p class="dossier-current">${esc(o.label)}</p>`}${o.archiveNote?`<p class="dossier-archive-note"><strong>档案备注</strong>${esc(o.archiveNote)}</p>`:''}${facts([...o.basic,...o.extras,...(p.profession?[{label:'游戏职业',value:o.profession||p.profession}]:[]),...(p.faction?[{label:'所属档案',value:p.faction}]:[])])}<p class="dossier-note">年龄以本形态基础档案的明确记载为准；“未公开”不代表没有可考经历，生日与战斗经验不用于推算年龄。</p><div class="dossier-arts"><h3>源石技艺</h3>${rating?`<div class="arts-rating"><span>源石技艺适应性</span><strong>${esc(rating)}</strong></div>`:''}<p>${esc(o.arts?.summary||'现有档案尚未确认可单列的具体源石技艺。')}</p><p class="dossier-note">适应性是档案测试项目，与具体技艺的表现分别记录；装备功能、种族天赋与玩法技能不直接等同于源石技艺。</p>${o.arts?.refs?.length?`<div class="dossier-evidence">材料：${o.arts.refs.map(r=>`<a href="${esc(o.source.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title||r.storyTitle)} ↗</a>`).join('；')}</div>`:''}</div><details class="dossier-details"><summary>体检与医疗记录</summary>${tests.length?facts(tests):'<p>本形态未列出可整理的综合体检数值。</p>'}${o.infection?`<h3>矿石病感染情况</h3><p>${esc(o.infection)}</p>`:''}${Object.keys(o.medical).length?facts(Object.entries(o.medical).map(([label,value])=>({label,value}))):''}</details><details class="dossier-details dossier-sources"><summary>档案出处与登记口径</summary><p>本页登记“${esc(record.name)}”当前所选档案的公开字段。异格分别登记；升变版本可在上方切换。涂黑、不明及未公开字段保留原档案口径，不用人物推测替代。</p><p>采用项目：${o.sectionTitles.map(esc).join('、')}。能力概述按档案记载转述。</p><a href="${esc(o.source.url)}" target="_blank" rel="noopener noreferrer">游戏本体档案文本 · 公开镜像 ↗</a>　<a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${esc(record.name)} · PRTS 转录入口 ↗</a></details></section>`;
 }
 function textOf(p){const r=get(p.id);return r?r.options.map(o=>[...o.basic,...o.extras].map(x=>x.label+' '+x.value).join(' ')+' '+Object.values(o.test).join(' ')+' '+(o.arts?.summary||'')).join(' '):'';}
 document.addEventListener('change',e=>{if(!e.target.matches('[data-profile-variant]'))return;const box=e.target.closest('[data-profile-id]'),id=box.dataset.profileId;selected.set(id,Number(e.target.value));const p=window.ROSTER_RENDER.index.get(id);box.outerHTML=render(p,true);document.querySelector('[data-profile-variant]')?.focus();});
 window.PROFILE_UI={get,render,textOf};
})();
